use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let limit: int = 200000
    let mut sieve: Vec<bool> = [true; 200001]
    let mut counts: Vec<int> = [0; 200001]
    let mut last: Vec<int> = [0; 200001]
    let mut c: int = 0
    let mut l: int = 0
    let mut i: int = 0
    while i <= limit {
        if i < 2 {
            sieve[i] = false
        } else if sieve[i] {
            c += 1
            l = i
            let mut j: int = i * i
            while j <= limit {
                sieve[j] = false
                j += i
            }
        }
        counts[i] = c
        last[i] = l
        i += 1
    }
    let mut first = true
    for line in text.lines() {
        let t = line.trim()
        if t.len() == 0 { continue }
        if first {
            first = false
            continue
        }
        let n: int = t.parse::<int>().unwrap_or(0)
        if n < 2 {
            println("0 none")
        } else {
            println("${counts[n]} ${last[n]}")
        }
    }
}

